def group_states(grid, start, goal):
    # Define movements (up, down, left, right)
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Get grid dimensions
    rows, cols = len(grid), len(grid[0])

    # Initialize visited set and queue for BFS
    visited = set()
    queue = [(start, [start])]

    # Initialize groups list
    groups = []

    while queue:
        (state, path) = queue.pop(0)
        if state not in visited:
            visited.add(state)
            # If this is the goal state, add the path to the groups list
            if state == goal:
                groups.append(path)
            else:
                # Get the current position of the state
                for i in range(rows):
                    for j in range(cols):
                        if grid[i][j] == state:
                            x, y = i, j
                            break
                    else:
                        continue
                    break

                # Explore neighbors
                for dx, dy in movements:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != "X":
                        neighbor_state = grid[nx][ny]
                        queue.append((neighbor_state, path + [neighbor_state]))

    # If there are any remaining unvisited states, add them to the groups list
    for i in range(rows):
        for j in range(cols):
            state = grid[i][j]
            if state != "X" and state not in visited:
                groups.append([state])

    return groups


grid = [[0, 2, 3, 5, 7], [1, "X", 4, "X", "X"], ["X", 9, 6, 10, 12], [17, "X", 8, "X", 14], [15, 13, 11, "X", 16]]
start = 0
goal = 16

print(group_states(grid, start, goal))
